const EXPECTED_TEAM_ID = 'T1CBEDLJY';
const EXPECTED_CHANNEL_ID = 'C0BS0N61D1R';
const EXPECTED_APP_ID = 'A08QT61M17H';
const ALLOWED_ACTIONS = new Set(['guardrail', 'final_approve']);
const MAX_REQUEST_AGE_SECONDS = 300;

const output = [];

for (const item of $input.all()) {
  const input = item.json || {};
  const headers = input.headers || {};
  const rawPayload = input.body?.payload;

  if (typeof rawPayload !== 'string' || !rawPayload.trim()) {
    continue;
  }

  let payload;
  let actionValue;

  try {
    payload = JSON.parse(rawPayload);
    const action = Array.isArray(payload.actions) ? payload.actions[0] : null;
    if (!action || typeof action.value !== 'string') {
      continue;
    }
    actionValue = JSON.parse(action.value);
  } catch {
    continue;
  }

  const action = payload.actions[0];
  const teamId = String(payload.team?.id || '').trim();
  const channelId = String(payload.channel?.id || payload.container?.channel_id || '').trim();
  const appId = String(payload.api_app_id || '').trim();
  const messageAppId = String(payload.message?.app_id || '').trim();
  const slackUserId = String(payload.user?.id || '').trim();
  const threadTs = String(payload.container?.thread_ts || payload.message?.thread_ts || '').trim();
  const messageTs = String(payload.container?.message_ts || payload.message?.ts || '').trim();
  const actionId = String(action.action_id || '').trim();
  const actionTs = String(action.action_ts || '').trim();
  const requestedAction = String(actionValue.action || '').trim();
  const investigationId = String(actionValue.investigation_id || '').trim();
  const draftVersion = Number(actionValue.draft_version);
  const requestTimestamp = Number(headers['x-slack-request-timestamp']);
  const signature = String(headers['x-slack-signature'] || '').trim();

  const timestampIsFresh =
    Number.isFinite(requestTimestamp) &&
    Math.abs(Math.floor(Date.now() / 1000) - requestTimestamp) <= MAX_REQUEST_AGE_SECONDS;

  const valid =
    payload.type === 'block_actions' &&
    teamId === EXPECTED_TEAM_ID &&
    channelId === EXPECTED_CHANNEL_ID &&
    appId === EXPECTED_APP_ID &&
    messageAppId === EXPECTED_APP_ID &&
    payload.container?.type === 'message' &&
    action.type === 'button' &&
    ALLOWED_ACTIONS.has(actionId) &&
    requestedAction === actionId &&
    slackUserId.length > 0 &&
    threadTs.length > 0 &&
    messageTs.length > 0 &&
    actionTs.length > 0 &&
    investigationId.length > 0 &&
    Number.isInteger(draftVersion) &&
    draftVersion >= 1 &&
    timestampIsFresh &&
    /^v0=[a-f0-9]{64}$/i.test(signature);

  if (!valid) {
    continue;
  }

  const guardrailId = String(actionValue.guardrail_id || '').trim() || null;
  const guardrailVersion = String(actionValue.guardrail_version || '').trim() || null;

  if (actionId === 'final_approve' && (!guardrailId || !guardrailVersion)) {
    continue;
  }

  output.push({
    json: {
      interaction_id: [
        teamId,
        channelId,
        messageTs,
        actionId,
        actionTs,
        slackUserId
      ].join(':'),
      team_id: teamId,
      channel_id: channelId,
      thread_ts: threadTs,
      slack_user_id: slackUserId,
      action: actionId,
      investigation_id: investigationId,
      draft_version: draftVersion,
      guardrail_id: guardrailId,
      guardrail_version: guardrailVersion
    }
  });
}

return output;

const input = $input.first()?.json || {};
const rawPayload = input.body?.payload;

if (typeof rawPayload !== 'string' || !rawPayload.trim()) {
  return [{ json: { parse_ok: false, parse_error: 'missing_payload' } }];
}

let payload;
try {
  payload = JSON.parse(rawPayload);
} catch {
  return [{ json: { parse_ok: false, parse_error: 'invalid_payload_json' } }];
}

const action = Array.isArray(payload.actions) ? payload.actions[0] || {} : {};
let actionValue = {};
try {
  actionValue = JSON.parse(String(action.value || '{}'));
} catch {
  actionValue = {};
}

const teamId = String(payload.team?.id || '').trim();
const channelId = String(payload.channel?.id || payload.container?.channel_id || '').trim();
const threadTs = String(payload.container?.thread_ts || payload.message?.thread_ts || '').trim();
const messageTs = String(payload.container?.message_ts || payload.message?.ts || '').trim();
const actionId = String(action.action_id || actionValue.action || '').trim();
const investigationId = String(actionValue.investigation_id || '').trim();
const draftVersion = Number(actionValue.draft_version || 0);
const originalBlocks = Array.isArray(payload.message?.blocks)
  ? payload.message.blocks.filter((block) => block && block.type !== 'actions')
  : [];

return [{
  json: {
    parse_ok: true,
    team_id: teamId,
    channel_id: channelId,
    thread_ts: threadTs,
    interaction_id: [teamId, channelId, messageTs, actionId, investigationId, String(draftVersion)].join(':'),
    slack_user_id: String(payload.user?.id || '').trim(),
    action: actionId,
    investigation_id: investigationId,
    draft_version: draftVersion,
    environment: String(actionValue.environment || '').trim(),
    zendesk_ticket_id: String(actionValue.zendesk_ticket_id || '').trim(),
    turn_id: String(actionValue.turn_id || '').trim(),
    draft_id: String(actionValue.draft_id || '').trim(),
    guardrail_id: String(actionValue.guardrail_id || '').trim() || null,
    guardrail_version: String(actionValue.guardrail_version || '').trim() || null,
    response_url: String(payload.response_url || '').trim(),
    original_text: String(payload.message?.text || '').trim(),
    original_blocks: originalBlocks
  }
}];
